"""
AlphaMind AI - Probabilistic Forecast Engine Schemas

Pydantic schemas for Probabilistic Forecasts, 95% Confidence Intervals, Probability Distributions,
Scenarios, and Forecast Metadata.
STRICT MANDATE: All output schemas must be probabilistic — zero static target prices or buy/sell signals.
"""

from __future__ import annotations

import time
import uuid

from pydantic import BaseModel, Field

MANDATORY_PROBABILISTIC_DISCLAIMER = (
    "PROBABILISTIC DISCLAIMER: All estimates generated by AlphaMind AI represent "
    "statistical probability distributions and potential scenario bounds derived from historical "
    "data and factor models. Forecasts are NOT guarantees, single-point target prices, or "
    "investment/trading recommendations."
)


class ConfidenceInterval95(BaseModel):
    lower_bound: float
    mean_estimate: float
    upper_bound: float
    confidence_level_pct: float = 95.0


class ProbabilityDistribution(BaseModel):
    bull_case_pct: float  # Probability %
    base_case_pct: float
    bear_case_pct: float
    stress_case_pct: float
    black_swan_case_pct: float


class ForecastScenario(BaseModel):
    scenario_name: str  # "Bull", "Base", "Bear", "Stress", "Black Swan"
    probability_pct: float
    implied_return_range_pct: list[float] = Field(default_factory=list)  # [min %, max %]
    key_assumptions: list[str] = Field(default_factory=list)
    supporting_evidence: list[str] = Field(default_factory=list)
    risk_factors: list[str] = Field(default_factory=list)


class ProbabilisticForecast(BaseModel):
    """
    Unified Probabilistic Forecast Schema.
    Strictly prohibits static price targets or buy/sell execution signals.
    """

    forecast_id: str = Field(default_factory=lambda: f"fcst_{uuid.uuid4().hex[:8]}")
    symbol: str
    target_horizon_days: int = 30
    created_at_utc: str = Field(
        default_factory=lambda: time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    )
    confidence_interval: ConfidenceInterval95
    probability_distribution: ProbabilityDistribution
    scenarios: list[ForecastScenario] = Field(default_factory=list)
    data_quality_score: float = 0.94
    known_unknowns: list[str] = Field(default_factory=list)
    contradictory_evidence: list[str] = Field(default_factory=list)
    model_ensemble_used: list[str] = Field(default_factory=list)
    disclaimer: str = MANDATORY_PROBABILISTIC_DISCLAIMER
